//! 🎟️ An original request retains its paid parent loan in a separate turn before constructor birth.
use super::{MemberOpenRequest,MemberOpenDiagnostic,receive_member_close};
use semio_framework_job::{OriginalCallerSourceParent,OriginalCallerSourceLoan,OriginalTurnFailure,StepContext};
use semio_framework_value::{RetirementDemand,ValueError,ValueRefusalKind,retained_clone::RetainedCloneStep};
use std::mem::ManuallyDrop;

/// 🪢️ Owns original request and source loan independently through admission, rejection and paid return.
pub struct MemberOpenSourceAdmission{pub(super) request:ManuallyDrop<Option<MemberOpenRequest>>,pub(super) source_loan:ManuallyDrop<Option<OriginalCallerSourceLoan>>}
impl MemberOpenSourceAdmission{
 pub fn new(request:MemberOpenRequest)->Self{Self{request:ManuallyDrop::new(Some(request)),source_loan:ManuallyDrop::new(None)}}
 pub fn request(&self)->Option<&MemberOpenRequest>{self.request.as_ref()}
 pub fn admit_source(&mut self,parent:&OriginalCallerSourceParent,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{let request=self.request.as_ref().ok_or_else(||diagnostic_error(MemberOpenDiagnostic::Stale))?;request.check_step_authority(cx).map_err(diagnostic_error)?;if let Some(loan)=self.source_loan.as_ref(){loan.validate_context(cx)?;return Ok(true)}*self.source_loan=parent.admit_loan(cx)?;Ok(false)}
 pub fn retirement_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if self.request.is_some(){return crate::os_store::snapshot_read::artifact_retirement_owner_demands(&self.request,body)}Ok(RetirementDemand{depth:usize::from(self.source_loan.is_some()),..Default::default()})}
 pub fn close_step(&mut self,parent:&OriginalCallerSourceParent,cx:&mut StepContext<'_>)->Result<RetainedCloneStep,OriginalTurnFailure>{if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()))}if self.request.is_some(){if let Some(loan)=self.source_loan.as_ref(){loan.validate_context(cx)?}else if !std::ptr::eq(cx.original_source_parent()?,parent){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"member request cleanup changed actual source parent").into())}if cx.should_yield(){return Ok(RetainedCloneStep::Progress(Default::default()))}let mut grant=cx.retained_grant();grant.maximum_copy_bytes=grant.maximum_copy_bytes.min(usize::try_from(cx.fuel_remaining().saturating_sub(1)).unwrap_or(usize::MAX));let result=crate::os_store::snapshot_read::artifact_retirement_owner_close(&mut self.request,grant);return receive_member_close(cx,result).map(|step|RetainedCloneStep::Progress(step.progress()))}let loan=self.source_loan.as_mut().unwrap();let result=loan.close_step(parent,cx)?;let progress=result.progress();if loan.terminal_is_empty(){self.source_loan.take();}Ok(if self.terminal_is_empty(){RetainedCloneStep::Complete(progress)}else{RetainedCloneStep::Progress(progress)})}
 pub fn terminal_is_empty(&self)->bool{self.request.is_none()&&self.source_loan.is_none()}
 pub fn next_copy_byte_demand(&self)->Result<usize,ValueError>{Ok(self.retirement_demands(0)?.copy_bytes)}
 pub fn next_capacity_byte_demand(&self,body:usize)->Result<usize,ValueError>{Ok(self.retirement_demands(body)?.capacity_bytes)}
 pub fn next_release_byte_demand(&self)->Result<usize,ValueError>{Ok(self.retirement_demands(0)?.release_bytes)}
 pub fn next_depth_demand(&self)->Result<usize,ValueError>{Ok(self.retirement_demands(0)?.depth)}
 pub fn terminal_drop_byte_demand(&self)->Option<usize>{self.terminal_is_empty().then_some(0)}
}
impl Drop for MemberOpenSourceAdmission{fn drop(&mut self){assert!(self.terminal_is_empty()||std::thread::panicking(),"member admission abandoned original request or paid source loan");if self.terminal_is_empty(){unsafe{ManuallyDrop::drop(&mut self.request);ManuallyDrop::drop(&mut self.source_loan)}}}}
/// 🧭️ Preserves one intrinsic member admission cause without constructing diagnostic text backing.
pub fn diagnostic_error(diagnostic:MemberOpenDiagnostic)->ValueError{let(kind,reason)=match diagnostic{MemberOpenDiagnostic::Unsealed=>(ValueRefusalKind::InvalidValue,"member original input is unsealed"),MemberOpenDiagnostic::Empty=>(ValueRefusalKind::InvalidValue,"member original input is empty"),MemberOpenDiagnostic::Expired=>(ValueRefusalKind::Canceled,"member original request expired"),MemberOpenDiagnostic::Identity=>(ValueRefusalKind::InvalidValue,"member original identity is invalid"),MemberOpenDiagnostic::Owner=>(ValueRefusalKind::InvalidValue,"member original owner is invalid"),MemberOpenDiagnostic::Capacity=>(ValueRefusalKind::OwnershipLimit,"member original capacity is refused"),MemberOpenDiagnostic::Stale=>(ValueRefusalKind::InvariantViolated,"member original source operation or generation is stale"),MemberOpenDiagnostic::Cancelled=>(ValueRefusalKind::Canceled,"member original request is cancelled"),MemberOpenDiagnostic::Malformed=>(ValueRefusalKind::InvalidValue,"member original input is malformed"),MemberOpenDiagnostic::Decode=>(ValueRefusalKind::InvalidValue,"member original snapshot decode is refused"),MemberOpenDiagnostic::Replay=>(ValueRefusalKind::InvalidValue,"member original History receiving is refused"),MemberOpenDiagnostic::Initialization=>(ValueRefusalKind::InvariantViolated,"member original initialization is refused")};ValueError::literal(kind,reason)}
